import os
import hashlib
import hmac
import urllib.parse
from flask import Flask, request, jsonify, send_file, abort
from functools import wraps
import re

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', os.urandom(32))
app.config['UPLOAD_DIR'] = '/var/app/uploads'
app.config['MAX_PATH_LEN'] = 255

# Middleware for request signing verification
def verify_signature(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        sig = request.headers.get('X-Signature', '')
        timestamp = request.headers.get('X-Timestamp', '')
        if not sig or not timestamp:
            abort(401)
        payload = f"{request.method}:{request.path}:{timestamp}"
        expected = hmac.new(
            app.config['SECRET_KEY'] if isinstance(app.config['SECRET_KEY'], bytes) else app.config['SECRET_KEY'].encode(),
            payload.encode(),
            hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(sig, expected):
            abort(403)
        return f(*args, **kwargs)
    return decorated

def sanitize_filename(filename):
    """Remove null bytes and validate characters"""
    if not filename:
        return None
    # Remove null bytes
    filename = filename.replace('\x00', '')
    # Block obvious traversal
    if '..' in filename or filename.startswith('/'):
        return None
    # Only allow safe characters
    if not re.match(r'^[a-zA-Z0-9._/%+-]+$', filename):
        return None
    if len(filename) > app.config['MAX_PATH_LEN']:
        return None
    return filename

def resolve_path(base_dir, user_path):
    """Safely resolve a user-provided path within base_dir"""
    # Decode percent-encoded characters for proper validation
    decoded_path = urllib.parse.unquote(user_path)
    # Sanitize the decoded path
    clean = sanitize_filename(decoded_path)
    if clean is None:
        return None
    # Construct full path
    full_path = os.path.join(base_dir, clean)
    # Normalize the path
    full_path = os.path.normpath(full_path)
    return full_path

@app.route('/api/files/<path:filepath>', methods=['GET'])
@verify_signature
def get_file(filepath):
    """Serve a file from the uploads directory"""
    base_dir = os.path.realpath(app.config['UPLOAD_DIR'])

    # Use resolve_path for safe path construction
    resolved = resolve_path(base_dir, filepath)
    if resolved is None:
        abort(400, description="Invalid file path")

    # Verify the resolved path is within base_dir
    if not resolved.startswith(base_dir):
        abort(403, description="Access denied")

    if not os.path.isfile(resolved):
        abort(404)

    return send_file(resolved)

@app.route('/api/files/download', methods=['POST'])
@verify_signature
def download_file():
    """Download a file by path specified in request body"""
    data = request.get_json()
    if not data or 'path' not in data:
        abort(400)

    user_path = data['path']
    if not isinstance(user_path, str):
        abort(400)

    base_dir = os.path.realpath(app.config['UPLOAD_DIR'])

    # Apply URL decoding to handle encoded paths from various clients
    decoded_once = urllib.parse.unquote(user_path)

    # Sanitize
    clean = sanitize_filename(decoded_once)
    if clean is None:
        abort(400, description="Invalid path")

    # Build and normalize
    full_path = os.path.normpath(os.path.join(base_dir, clean))

    # Security check: ensure path is under base_dir
    if not full_path.startswith(base_dir):
        abort(403)

    if not os.path.isfile(full_path):
        abort(404)

    return send_file(full_path)

@app.route('/api/files/batch', methods=['POST'])
@verify_signature
def batch_download():
    """Download multiple files, paths in request body"""
    data = request.get_json()
    if not data or 'paths' not in data or not isinstance(data['paths'], list):
        abort(400)

    base_dir = os.path.realpath(app.config['UPLOAD_DIR'])
    results = []

    for user_path in data['paths'][:20]:  # Limit batch size
        if not isinstance(user_path, str):
            continue

        # Decode the path - clients may double-encode special chars
        step1 = urllib.parse.unquote(user_path)

        # Check for traversal BEFORE second decode
        if '..' in step1 or step1.startswith('/'):
            continue

        # Second decode for doubly-encoded paths from legacy clients
        step2 = urllib.parse.unquote(step1)

        # Build final path
        full_path = os.path.normpath(os.path.join(base_dir, step2))

        # Verify containment
        if not full_path.startswith(base_dir + os.sep) and full_path != base_dir:
            continue

        if os.path.isfile(full_path):
            results.append({
                'path': user_path,
                'size': os.path.getsize(full_path),
                'exists': True
            })
        else:
            results.append({'path': user_path, 'exists': False})

    return jsonify({'files': results})

if __name__ == '__main__':
    os.makedirs(app.config['UPLOAD_DIR'], exist_ok=True)
    app.run(host='127.0.0.1', port=8080)
